func countSignFlips(nums: ArrayList<Int64>): Int64 {
    /*
    Count how many times the sign changes between consecutive non-zero elements.
    Zeros are ignored when tracking the previous non-zero sign.
    >>> countSignFlips(ArrayList<Int64>([1, -2, 3, -4]))
    3
    >>> countSignFlips(ArrayList<Int64>([1, 0, -2, 0, -3, 0, 4]))
    2
    */
    var prevSign: Int64 = 0
    var flips: Int64 = 0
    for (x in nums) {
        if (x == 0) {
            continue
        }
        let sign: Int64 = if (x > 0) { 1 } else { -1 }
        if (prevSign != 0 && sign != prevSign) {
            flips++
        }
        prevSign = sign
    }
    return flips
}

