func stripEdgeRune(s: String, target: Rune): String {
    /*
    Remove all leading and trailing occurrences of target from s.
    Occurrences of target in the middle of s are preserved.
    >>> stripEdgeRune("---a--b---", r'-')
    "a--b"
    >>> stripEdgeRune("xxxx", r'x')
    ""
    */
    let runes = s.toRuneArray()
    var left: Int64 = 0
    var right: Int64 = runes.size - 1
    while (left <= right && runes[left] == target) {
        left++
    }
    while (right >= left && runes[right] == target) {
        right--
    }
    var res = ""
    for (i in left..right + 1) {
        res += runes[i].toString()
    }
    return res
}

