func stepwiseCap(nums: ArrayList<Int64>, maxStep: Int64): ArrayList<Int64> {
    /*
    Build a new list starting with nums[0] where each subsequent value is clamped
    to differ from the previous output value by at most maxStep (maxStep >= 0).
    >>> stepwiseCap(ArrayList<Int64>([10, 20, 5, 6]), 3)
    [10, 13, 10, 7]
    >>> stepwiseCap(ArrayList<Int64>([1, 10, 10]), 0)
    [1, 1, 1]
    */
    let res = ArrayList<Int64>()
    if (nums.isEmpty()) {
        return res
    }
    res.add(nums[0])
    for (i in 1..nums.size) {
        let prev = res[res.size - 1]
        let cur = nums[i]
        if (cur > prev + maxStep) {
            res.add(prev + maxStep)
        } else if (cur < prev - maxStep) {
            res.add(prev - maxStep)
        } else {
            res.add(cur)
        }
    }
    return res
}

