    /*
    Replace all ASCII digits ('0'..'9') with '*' except the last keepTail digits.
    Non-digit characters remain unchanged. Assume keepTail >= 0.
    >>> maskMiddleDigits("card-4111-2222-3333", 4)
    "card-****-****-3333"
    >>> maskMiddleDigits("123", 5)
    "123"
    */
    let runes = s.toRuneArray()
    var digitCount: Int64 = 0
    for (r in runes) {
        if (r >= r'0' && r <= r'9') {
            digitCount++
        }
    }
    let toMask: Int64 = if (digitCount > keepTail) { digitCount - keepTail } else { 0 }
    var masked: Int64 = 0
    var res = ""
    for (r in runes) {
        if (r >= r'0' && r <= r'9' && masked < toMask) {
            res += "*"
            masked++
        } else {
            res += r.toString()
        }
    }
    return res
}

