func weightedWindowMax(nums: ArrayList<Int64>): Option<Int64> {
    /*
    Compute nums[i - 1] + 2 * nums[i] + nums[i + 1] for all 1 <= i <= nums.size - 2
    and return Some(maximum). Return None if nums has fewer than 3 elements.
    >>> weightedWindowMax(ArrayList<Int64>([1, 4, 2, 5, 1]))
    Some(13)
    >>> weightedWindowMax(ArrayList<Int64>([10, 20]))
    None
    */
    if (nums.size < 3) {
        return None
    }
    var best = nums[0] + 2 * nums[1] + nums[2]
    for (i in 2..nums.size - 1) {
        let val = nums[i - 1] + 2 * nums[i] + nums[i + 1]
        if (val > best) {
            best = val
        }
    }
    return Some(best)
}

