func mirrorParityCount(nums: ArrayList<Int64>): Int64 {
    /*
    Count pairs (i, nums.size - 1 - i) with i < nums.size - 1 - i
    where both elements have the same parity (both even or both odd).
    >>> mirrorParityCount(ArrayList<Int64>([2, 3, 5, 4]))
    2
    >>> mirrorParityCount(ArrayList<Int64>([7]))
    0
    */
    let n = nums.size
    var count: Int64 = 0
    for (i in 0..n / 2) {
        let p1 = ((nums[i] % 2) + 2) % 2
        let p2 = ((nums[n - 1 - i] % 2) + 2) % 2
        if (p1 == p2) {
            count++
        }
    }
    return count
}

