func compactZeroGaps(nums: ArrayList<Int64>): ArrayList<Int64> {
    /*
    Replace each maximal contiguous run of zeros of length k with a single -k.
    Non-zero elements remain unchanged in their original order.
    >>> compactZeroGaps(ArrayList<Int64>([5, 0, 0, 0, 3, 0, 8]))
    [5, -3, 3, -1, 8]
    >>> compactZeroGaps(ArrayList<Int64>([0, 0, 0, 0]))
    [-4]
    */
    let res = ArrayList<Int64>()
    var zeros: Int64 = 0
    for (x in nums) {
        if (x == 0) {
            zeros++
        } else {
            if (zeros > 0) {
                res.add(-zeros)
                zeros = 0
            }
            res.add(x)
        }
    }
    if (zeros > 0) {
        res.add(-zeros)
    }
    return res
}

