func stableBucketPartition(nums: ArrayList<Int64>, pivot: Int64): ArrayList<Int64> {
    /*
    Return a new list with elements < pivot first, then == pivot, then > pivot,
    preserving the relative order of elements within each group.
    >>> stableBucketPartition(ArrayList<Int64>([5, 1, 3, 5, 2, 3, 0]), 3)
    [1, 2, 0, 3, 3, 5, 5]
    >>> stableBucketPartition(ArrayList<Int64>([-1, -5, -1, 0]), -1)
    [-5, -1, -1, 0]
    */
    let less = ArrayList<Int64>()
    let equal = ArrayList<Int64>()
    let greater = ArrayList<Int64>()
    for (x in nums) {
        if (x < pivot) {
            less.add(x)
        } else if (x == pivot) {
            equal.add(x)
        } else {
            greater.add(x)
        }
    }
    let res = ArrayList<Int64>()
    for (x in less) { res.add(x) }
    for (x in equal) { res.add(x) }
    for (x in greater) { res.add(x) }
    return res
}

