import std.collection.{ArrayList, HashMap}

func firstUniquePairSum(nums: ArrayList<Int64>): Option<Int64> {
    /*
    Find the first element and the last element in nums that appear exactly once.
    If only one element appears once, it counts as both the first and the last.
    Return Some(first + last), or None if no element has frequency 1.
    >>> firstUniquePairSum(ArrayList<Int64>([4, 2, 4, 7, 9, 7, 1]))
    Some(3)
    >>> firstUniquePairSum(ArrayList<Int64>([3, 3, 8, 8]))
    None
    */
    let freq = HashMap<Int64, Int64>()
    for (x in nums) {
        let c = match (freq.get(x)) {
            case Some(v) => v
            case None => 0
        }
        freq.add(x, c + 1)
    }
    var first: Option<Int64> = None
    var last: Option<Int64> = None
    for (x in nums) {
        if (freq.get(x) == Some(1)) {
            if (first == None) {
                first = Some(x)
            }
            last = Some(x)
        }
    }
    match ((first, last)) {
        case (Some(a), Some(b)) => return Some(a + b)
        case _ => return None
    }
}

