func runLengthCheck(encoded: String, raw: String): Bool {
    /*
    Verify whether encoded is a valid run-length encoding of raw.
    Each token in encoded must be an ASCII letter followed by a positive integer count.
    >>> runLengthCheck("a3b2c1", "aaabbc")
    true
    >>> runLengthCheck("a0", "")
    false
    */
    let enc = encoded.toRuneArray()
    let txt = raw.toRuneArray()
    var i: Int64 = 0
    var j: Int64 = 0
    while (i < enc.size) {
        let ch = enc[i]
        if (!((ch >= r'a' && ch <= r'z') || (ch >= r'A' && ch <= r'Z'))) { return false }
        i++
        if (i >= enc.size || enc[i] < r'0' || enc[i] > r'9') { return false }
        var cnt: Int64 = 0
        while (i < enc.size && enc[i] >= r'0' && enc[i] <= r'9') {
            cnt = cnt * 10 + Int64(UInt32(enc[i]) - UInt32(r'0'))
            i++
            if (cnt > txt.size - j) { return false }
        }
        if (cnt == 0 || j + cnt > txt.size) { return false }
        for (k in 0..cnt) {
            if (txt[j + k] != ch) { return false }
        }
        j += cnt
    }
    return j == txt.size
}

