func prefixDominantCount(nums: ArrayList<Int64>, threshold: Int64): Int64 {
    /*
    Scan nums from left to right. For each index i >= 1, let m be the minimum of
    nums[0..i-1] and s be the sum of nums[0..i]. Count indices i >= 1 where
    nums[i] > m + threshold and s > 0.
    >>> prefixDominantCount(ArrayList<Int64>([2, 5, 1, 7, 10]), 3)
    2
    >>> prefixDominantCount(ArrayList<Int64>([3, 3, 3]), 0)
    0
