    if (nums.isEmpty()) {
        return 0
    }
    var sum: Int64 = nums[0]
    var minPrefix: Int64 = nums[0]
    var count: Int64 = 0
    for (i in 1..nums.size) {
        let x = nums[i]
        sum += x
        if (x > minPrefix + threshold && sum > 0) {
            count++
        }
        if (x < minPrefix) {
            minPrefix = x
        }
    }
    return count
}

