import std.collection.ArrayList

func evalSwitchPipeline(ops: ArrayList<String>, initVal: Int64): Option<Int64> {
    /*
    Simulate a stateful accumulator starting at initVal in NORMAL mode.
    Supported ops: 'FLIP' (toggle NORMAL/INVERT), 'ADD k' (+k in NORMAL, -k in INVERT),
    'CLAMP lo hi' (clamp to [lo, hi] if lo <= hi), 'RESET' (restore initVal & NORMAL).
    Return Some(finalAcc), or None if any operation or integer argument is invalid.
    >>> evalSwitchPipeline(ArrayList<String>(["ADD 5", "FLIP", "ADD 2"]), 10)
    Some(13)
    >>> evalSwitchPipeline(ArrayList<String>(["ADD abc"]), 0)
    None
    */
    let parseInt = { tok: String =>
        let rs = tok.toRuneArray()
        if (rs.isEmpty()) { return Option<Int64>.None }
        var idx: Int64 = if (rs[0] == r'-' || rs[0] == r'+') { 1 } else { 0 }
        if (idx >= rs.size) { return Option<Int64>.None }
        var v: Int64 = 0
        for (k in idx..rs.size) {
            if (rs[k] < r'0' || rs[k] > r'9') { return Option<Int64>.None }
            v = v * 10 + Int64(UInt32(rs[k]) - UInt32(r'0'))
        }
        return Some(if (rs[0] == r'-') { -v } else { v })
    }
    var acc = initVal
    var invert = false
    for (op in ops) {
        let parts = ArrayList<String>()
        for (p in op.split(" ")) { if (!p.isEmpty()) { parts.add(p) } }
        if (parts.isEmpty()) { return None }
        let cmd = parts[0]
        if (cmd == "FLIP" && parts.size == 1) { invert = !invert }
        else if (cmd == "RESET" && parts.size == 1) { acc = initVal; invert = false }
        else if (cmd == "ADD" && parts.size == 2) {
            match (parseInt(parts[1])) {
                case Some(k) => acc = if (invert) { acc - k } else { acc + k }
                case None => return None
            }
        } else if (cmd == "CLAMP" && parts.size == 3) {
            match ((parseInt(parts[1]), parseInt(parts[2]))) {
                case (Some(lo), Some(hi)) => if (lo <= hi) {
                    if (acc < lo) { acc = lo } else if (acc > hi) { acc = hi }
                }
                case _ => return None
            }
        } else { return None }
    }
    return Some(acc)
}

