func coalesceQuotaBlocks(loads: ArrayList<Int64>, maxSum: Int64, maxLen: Int64): ArrayList<Int64> {
    /*
    Partition non-negative loads greedily from left to right into contiguous blocks,
    where each block has at most maxLen > 0 elements and sum <= maxSum >= 0.
    If a single element exceeds maxSum, it forms a 1-element block. Return block sums.
    >>> coalesceQuotaBlocks(ArrayList<Int64>([3, 4, 2, 5, 1, 1]), 7, 2)
    [7, 7, 2]
    >>> coalesceQuotaBlocks(ArrayList<Int64>([12, 3, 4]), 7, 3)
    [12, 7]
    */
    let res = ArrayList<Int64>()
    if (loads.isEmpty()) {
        return res
    }
    var curSum: Int64 = 0
    var curLen: Int64 = 0
    for (x in loads) {
        if (curLen > 0 && (curLen + 1 > maxLen || curSum + x > maxSum)) {
            res.add(curSum)
            curSum = x
            curLen = 1
        } else {
            curSum += x
            curLen++
        }
    }
    res.add(curSum)
    return res
}

