import std.collection.ArrayList

func alignColumnsCSV(rows: ArrayList<String>): ArrayList<String> {
    /*
    Split each row by ',' and compute the maximum character width of each column.
    Right-pad each present field with spaces to its column width and join fields
    in each row with " | ". Return an empty list if rows is empty.
    >>> alignColumnsCSV(ArrayList<String>(["a,bc,d", "hello,x", "z,yy,www"]))
    ["a     | bc | d  ", "hello | x ", "z     | yy | www"]
    >>> alignColumnsCSV(ArrayList<String>(["1,22", "333,4"]))
    ["1   | 22", "333 | 4 "]
    */
    let out = ArrayList<String>()
    if (rows.isEmpty()) { return out }
    let parsed = ArrayList<Array<String>>()
    var maxCols: Int64 = 0
    for (row in rows) {
        let cols = row.split(",")
        parsed.add(cols)
        if (cols.size > maxCols) { maxCols = cols.size }
    }
    let widths = ArrayList<Int64>()
    for (_ in 0..maxCols) { widths.add(0) }
    for (cols in parsed) {
        for (c in 0..cols.size) {
            let w = cols[c].toRuneArray().size
            if (w > widths[c]) { widths[c] = w }
        }
    }
    for (cols in parsed) {
        var line = ""
        for (c in 0..cols.size) {
            if (c > 0) { line += " | " }
            line += cols[c]
            let pad = widths[c] - cols[c].toRuneArray().size
            for (_ in 0..pad) { line += " " }
        }
        out.add(line)
    }
    return out
}

