import std.collection.ArrayList

func simulatePacketQueue(arrivals: ArrayList<Int64>, processTime: Int64, capacity: Int64): Int64 {
    /*
    Simulate a single-server queue with waiting buffer capacity (capacity >= 0).
    arrivals is non-decreasing; each accepted packet takes processTime > 0. At arrival t,
    packets finishing <= t leave first; if fewer than capacity packets are waiting (i.e. total
    in-system < capacity + 1), the packet is accepted, else dropped. Return dropped count.
    >>> simulatePacketQueue(ArrayList<Int64>([0, 1, 2, 3, 10]), 4, 1)
    2
    >>> simulatePacketQueue(ArrayList<Int64>([1, 2, 3]), 5, 0)
    2
    */
    let finishes = ArrayList<Int64>()
    var head: Int64 = 0
    var dropped: Int64 = 0
    for (t in arrivals) {
        while (head < finishes.size && finishes[head] <= t) {
            head++
        }
        let active = finishes.size - head
        if (active < capacity + 1) {
            let start = if (active == 0) { t } else {
                let last = finishes[finishes.size - 1]
                if (t > last) { t } else { last }
            }
            finishes.add(start + processTime)
        } else {
            dropped++
        }
    }
    return dropped
}

