import std.collection.ArrayList

func simulateHysteresisSegments(samples: ArrayList<Int64>, lowThresh: Int64, highThresh: Int64): ArrayList<Int64> {
    /*
    Segment samples using a two-threshold hysteresis state machine starting in LOW.
    If samples is empty or lowThresh >= highThresh, return an empty list.
    In LOW, a sample >= highThresh switches to HIGH (starting a new segment at that sample);
    in HIGH, a sample <= lowThresh switches to LOW. Return the lengths of all segments.
    >>> simulateHysteresisSegments(ArrayList<Int64>([1, 5, 10, 8, 2, 1, 9]), 3, 7)
    [2, 2, 2, 1]
    >>> simulateHysteresisSegments(ArrayList<Int64>([10, 8, 9]), 3, 7)
    [3]
    */
    let res = ArrayList<Int64>()
    if (samples.isEmpty() || lowThresh >= highThresh) {
        return res
    }
    var inHigh = false
    var curLen: Int64 = 0
    for (x in samples) {
        if (!inHigh && x >= highThresh) {
            if (curLen > 0) { res.add(curLen) }
            inHigh = true
            curLen = 1
        } else if (inHigh && x <= lowThresh) {
            if (curLen > 0) { res.add(curLen) }
            inHigh = false
            curLen = 1
        } else {
            curLen++
        }
    }
    if (curLen > 0) { res.add(curLen) }
    return res
}

