import std.collection.{ArrayList, HashMap}

func evalKeyedTemplate(tmpl: String, kvPairs: ArrayList<String>): String {
    /*
    Substitute {key} placeholders in tmpl using flat key-value pairs [k0, v0, k1, v1, ...].
    Unknown keys or unclosed '{' are kept literally; a nested '{' restarts placeholder scanning.
    >>> evalKeyedTemplate("Hi {name}, id={id}!", ArrayList<String>(["name", "Ada", "id", "42"]))
    "Hi Ada, id=42!"
    >>> evalKeyedTemplate("unclosed {a and {ok}", ArrayList<String>(["ok", "YES"]))
    "unclosed {a and YES"
    */
    let mp = HashMap<String, String>()
    var p: Int64 = 0
    while (p + 1 < kvPairs.size) {
        mp.add(kvPairs[p], kvPairs[p + 1])
        p += 2
    }
    let rs = tmpl.toRuneArray()
    var res = ""
    var i: Int64 = 0
    while (i < rs.size) {
        if (rs[i] == r'{') {
            var j = i + 1
            var key = ""
            while (j < rs.size && rs[j] != r'}' && rs[j] != r'{') {
                key += rs[j].toString()
                j++
            }
            if (j < rs.size && rs[j] == r'}') {
                res += match (mp.get(key)) {
                    case Some(v) => v
                    case None => "{" + key + "}"
                }
                i = j + 1
            } else { res += "{"; i++ }
        } else { res += rs[i].toString(); i++ }
    }
    return res
}

