import std.collection.ArrayList

func countActiveSensors(grid: ArrayList<ArrayList<Int64>>): Int64 {
    /*
    In a grid where 0 = empty, 1 = sensor, and 2 = wall, a sensor is covered if at least
    one orthogonal neighbor is a sensor (1) OR at least two orthogonal neighbors are walls (2).
    Return the total number of covered sensors.
    >>> countActiveSensors(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 1, 2])]))
    1
    >>> countActiveSensors(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1])]))
    0
    */
    let rows = grid.size
    var covered: Int64 = 0
    let dr = [-1, 1, 0, 0]
    let dc = [0, 0, -1, 1]
    for (r in 0..rows) {
        for (c in 0..grid[r].size) {
            if (grid[r][c] != 1) { continue }
            var hasSensor = false
            var walls: Int64 = 0
            for (k in 0..4) {
                let nr = r + dr[k]
                let nc = c + dc[k]
                if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].size) {
                    if (grid[nr][nc] == 1) { hasSensor = true }
                    else if (grid[nr][nc] == 2) { walls++ }
                }
            }
            if (hasSensor || walls >= 2) { covered++ }
        }
    }
    return covered
}

