import std.collection.ArrayList

func routeLoadToBuckets(weights: ArrayList<Int64>, numBuckets: Int64): ArrayList<Int64> {
    /*
    Maintain numBuckets > 0 buckets initialized to 0. Process each weight in order,
    adding it to the bucket with the smallest current total (ties broken by smallest
    bucket index). Return the final total load of each bucket.
    >>> routeLoadToBuckets(ArrayList<Int64>([5, 2, 4, 3, 1]), 3)
    [5, 5, 5]
    >>> routeLoadToBuckets(ArrayList<Int64>([]), 4)
    [0, 0, 0, 0]
    */
    let buckets = ArrayList<Int64>()
    for (_ in 0..numBuckets) {
        buckets.add(0)
    }
    for (w in weights) {
        var bestIdx: Int64 = 0
        for (i in 1..numBuckets) {
            if (buckets[i] < buckets[bestIdx]) {
                bestIdx = i
            }
        }
        buckets[bestIdx] += w
    }
    return buckets
}

